CREATE TABLE IF NOT EXISTS clubhouse_events (id TEXT PRIMARY KEY, season INTEGER NOT NULL, event_type TEXT NOT NULL, manager_id TEXT, occurred_at TEXT NOT NULL, source TEXT NOT NULL CHECK (source IN ('league', 'draft', 'weekly', 'commissioner')), source_id TEXT, title TEXT NOT NULL, story TEXT, payload_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(source, source_id));
CREATE INDEX IF NOT EXISTS idx_clubhouse_events_season_type ON clubhouse_events(season, event_type, occurred_at);
CREATE INDEX IF NOT EXISTS idx_clubhouse_events_manager ON clubhouse_events(manager_id, occurred_at);
CREATE TABLE IF NOT EXISTS achievement_definitions (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL, icon TEXT NOT NULL, category TEXT NOT NULL CHECK (category IN ('league', 'draft', 'participation', 'family_spirit', 'memory')), award_method TEXT NOT NULL CHECK (award_method IN ('automatic', 'commissioner')), repeatable INTEGER NOT NULL DEFAULT 0 CHECK (repeatable IN (0, 1)), rule_key TEXT, active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0, 1)), sort_order INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS achievement_awards (id TEXT PRIMARY KEY, achievement_id TEXT NOT NULL REFERENCES achievement_definitions(id), manager_id TEXT NOT NULL, season INTEGER NOT NULL, award_key TEXT NOT NULL, event_id TEXT REFERENCES clubhouse_events(id), awarded_by_manager_id TEXT, awarded_at TEXT NOT NULL, note TEXT, photo_url TEXT, revoked_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_achievement_awards_manager_season ON achievement_awards(manager_id, season, awarded_at);
CREATE UNIQUE INDEX IF NOT EXISTS idx_achievement_awards_once ON achievement_awards(achievement_id, manager_id, award_key) WHERE revoked_at IS NULL;
PRAGMA optimize;
